#include <stdio.h>
#include <stdlib.h>

int *rent_one(int v) {
    int *p = malloc(sizeof(int));
    if (p == NULL) {
        return NULL;
    }
    *p = v;
    return p;
}

int main(void) {
    int rented = 0;
    int returned = 0;

    int *p = rent_one({x});
    rented++;
    printf("第 1 间放的是 %d\n", *p);
    free(p);
    returned++;

